import{f as o,o as a,c as t,a2 as r}from"./chunks/framework.Cd9rfTEn.js";const m=JSON.parse('{"title":"Contraste del documento externo \\"NucleoTransversal-Modelo\\" con la especificación de GoodApps Cooperativas","description":"","frontmatter":{},"headers":[],"relativePath":"revision-externa/NucleoTransversal-contraste.md","filePath":"revision-externa/NucleoTransversal-contraste.md","lastUpdated":null}'),i={name:"revision-externa/NucleoTransversal-contraste.md"};function n(s,e,d,c,l,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="contraste-del-documento-externo-nucleotransversal-modelo-con-la-especificacion-de-goodapps-cooperativas" tabindex="-1">Contraste del documento externo &quot;NucleoTransversal-Modelo&quot; con la especificación de GoodApps Cooperativas <a class="header-anchor" href="#contraste-del-documento-externo-nucleotransversal-modelo-con-la-especificacion-de-goodapps-cooperativas" aria-label="Permalink to &quot;Contraste del documento externo &quot;NucleoTransversal-Modelo&quot; con la especificación de GoodApps Cooperativas&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Documento revisado</td><td><code>NucleoTransversal-Modelo.md</code> (1.446 líneas, 17 capítulos, 6-11-2026, autor externo)</td></tr><tr><td>Contrastado contra</td><td><code>docs/especificacion/</code> (maestra, DEC-001 a DEC-092, preguntas abiertas, anexos M01 a M19 y T01 a T12) y <code>procoop-relevamiento/</code> (catálogo de 659 tablas, reglas de negocio, fichas de integración)</td></tr><tr><td>Fecha</td><td>7-11-2026</td></tr><tr><td>Estado</td><td>Informe de revisión. El 10-11-2026 el solicitante aprobó, de a una, las 11 incorporaciones de prioridad alta (A1 a A11) con la opción recomendada y la corrección de las 11 inconsistencias internas: quedaron registradas como DEC-093 a DEC-104 y PA-FIS-23 a PA-FIS-26, y se aplican en los anexos. Las prioridades media y baja (5.2 y 5.3) no se aplicaron. <em>Reemplazado (10-11-2026): &quot;Informe de revisión. No modifica la especificación; las incorporaciones requieren aprobación.&quot;</em></td></tr><tr><td>Detalle por capítulo</td><td><code>_trabajo/contraste-01-04.md</code>, <code>contraste-05-07.md</code>, <code>contraste-08-10.md</code>, <code>contraste-11-13-original.md</code> y <code>contraste-11-13.md</code> (dos revisiones independientes de los mismos capítulos), <code>contraste-14-16.md</code></td></tr></tbody></table><h2 id="_1-conclusion" tabindex="-1">1. Conclusión <a class="header-anchor" href="#_1-conclusion" aria-label="Permalink to &quot;1. Conclusión&quot;">​</a></h2><p>El documento es un trabajo serio de relevamiento de ProCoop y la mayoría de sus principios funcionales coinciden con los nuestros: datos en filas y no en columnas, historia con vigencia, identidad única de la persona, numeración sin huecos, separación de funciones, secretos fuera del código. Pero tiene tres problemas de fondo:</p><ol><li><strong>Parte de una arquitectura distinta de la nuestra.</strong> Propone una instalación aislada por cooperativa, GestionApps como sistema base y claves foráneas declaradas en una base relacional. Nuestra especificación decidió lo contrario: base única compartida con <code>tenantId</code> (DEC-002), stack propio Node/MongoDB (DEC-001) e integridad validada en el dominio. En esos puntos prevalece nuestra especificación.</li><li><strong>Está desactualizado respecto de lo nuestro.</strong> Marca como &quot;Sin analizar&quot; medición, mora, stock, técnica, sueldos y canales, que en nuestra especificación tienen anexo completo. De sus 58 definiciones pendientes, 49 ya están respondidas por una DEC, una PA o un requisito.</li><li><strong>Describe mal varias cosas de ProCoop.</strong> Hay unos 50 errores de hecho, casi todos menores, pero algunos importantes: la base imponible, la simulación de cuadros, el CESP de la liquidación de servicios públicos, el circuito de firmas de órdenes de pago y las provincias de Ingresos Brutos.</li></ol><p>Lo valioso es que, al contrastarlo, aparecen <strong>huecos reales de nuestra especificación</strong>, sobre todo en tres frentes: la decisión de varias entidades jurídicas por cooperativa (DEC-064) quedó incompleta en varias colecciones, hay temas fiscales propios de la cooperativa que no tratamos, y hay detalles de modelo (frentes, zonificación, verificador de integridad) que conviene sumar.</p><h2 id="_2-resultado-por-veredicto" tabindex="-1">2. Resultado por veredicto <a class="header-anchor" href="#_2-resultado-por-veredicto" aria-label="Permalink to &quot;2. Resultado por veredicto&quot;">​</a></h2><p>Se evaluaron 112 temas (una fila por cada subsección del documento).</p><table tabindex="0"><thead><tr><th>Veredicto</th><th>Cantidad</th></tr></thead><tbody><tr><td>Coincide</td><td>47</td></tr><tr><td>Coincide parcial (lo tenemos, el documento aporta un detalle)</td><td>44</td></tr><tr><td>Contradice una decisión nuestra</td><td>15</td></tr><tr><td>Error del documento como veredicto principal</td><td>3</td></tr><tr><td>Nuevo útil</td><td>1</td></tr><tr><td>Nuevo descartable</td><td>2</td></tr></tbody></table><p>Además de las filas, cada borrador lista los errores de hecho del documento (unos 50 en total) y los aportes priorizados (unos 40).</p><h2 id="_3-lo-que-esta-bien" tabindex="-1">3. Lo que está bien <a class="header-anchor" href="#_3-lo-que-esta-bien" aria-label="Permalink to &quot;3. Lo que está bien&quot;">​</a></h2><p>El documento acierta, y coincide con nuestra especificación, en:</p><ul><li><strong>Estructura:</strong> varias empresas (personas jurídicas) por cooperativa con CUIT, condición fiscal y certificados propios (DEC-064); sucursales y puntos de venta; usuario con acceso a varias empresas.</li><li><strong>Personas:</strong> persona única con roles (socio, cliente, proveedor, empleado); vínculos con vigencia; transferencia de titularidad; alta asistida con control de duplicados; bajas por tipo; datos personales bajo la Ley 25.326 (M01, DEC-076).</li><li><strong>Domicilios e inmuebles:</strong> domicilio normalizado contra un maestro de calles (DEC-046); inmueble independiente de la cuenta con unidades funcionales; nomenclatura catastral configurable (M01).</li><li><strong>Tarifas:</strong> cuadros versionados con estados; componentes como filas; coeficientes y series con vigencia; prorrateo; simulación antes de aprobar (M04).</li><li><strong>Comprobantes:</strong> cabecera común y relaciones entre comprobantes; anulación por nota de crédito; numeración transaccional sin huecos; hasta cuatro vencimientos; CAE con CAEA de contingencia (M05, M06, DEC-018, DEC-035, DEC-038).</li><li><strong>Impuestos y contabilidad:</strong> IVA por reglas con vigencia; percepciones separadas; padrones y retenciones con vigencia; Convenio Multilateral; plan de cuentas jerárquico con mapeo a plan sectorial; asientos automáticos; ajuste por inflación; presupuesto (M06, M15).</li><li><strong>Tesorería y seguridad:</strong> libro único de movimientos de fondos (<code>treasuryMovements</code>, M14); echeq; órdenes de pago con firmas por monto; conciliación; identidad única con segundo factor; permisos por acción y alcance; pares incompatibles; auditoría con lecturas sensibles; bóveda de secretos (T02, T08, DEC-074).</li><li><strong>Migración:</strong> unificación del padrón, rechazo de huérfanos con informe, normalización de domicilios y usuarios sin contraseña con invitación de activación (T07, PA-MIG-07).</li><li><strong>Cifras de ProCoop confirmadas:</strong> 659 tablas en 31 módulos; <code>SERVICIO</code> 150 columnas, <code>PROD_SER</code> 90, <code>CATE_SER</code> 97, <code>CATTARIF</code> 44, <code>COMPROB</code> 38, <code>SUMSOC</code> 72, <code>SERSOC</code> 119, <code>TIPO_FAC</code> 57, <code>PROPIEDA</code> 102; la terna tipo, punto de venta y número en exactamente 53 tablas; 38 tablas de stock, 89 de técnica, redes y telefonía, 56 de sueldos.</li></ul><h2 id="_4-lo-que-esta-mal" tabindex="-1">4. Lo que está mal <a class="header-anchor" href="#_4-lo-que-esta-mal" aria-label="Permalink to &quot;4. Lo que está mal&quot;">​</a></h2><h3 id="_4-1-contradicciones-con-decisiones-nuestras-prevalece-nuestra-especificacion" tabindex="-1">4.1 Contradicciones con decisiones nuestras (prevalece nuestra especificación) <a class="header-anchor" href="#_4-1-contradicciones-con-decisiones-nuestras-prevalece-nuestra-especificacion" aria-label="Permalink to &quot;4.1 Contradicciones con decisiones nuestras (prevalece nuestra especificación)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tema</th><th>El documento propone</th><th>Nuestra especificación</th><th>Por qué prevalece lo nuestro</th></tr></thead><tbody><tr><td>Instalación (DD-08, 2.1, 15)</td><td>Una instalación aislada por cooperativa</td><td>Base única compartida con <code>tenantId</code> (DEC-002)</td><td>Es la base del modelo SaaS; la base por cooperativa es la deuda que reemplazamos.</td></tr><tr><td>Sistema base (DD-01)</td><td>GestionApps como base</td><td>Stack propio sobre el patrón Connectia (DEC-001, DEC-007)</td><td>GestionApps no forma parte de nuestras fuentes.</td></tr><tr><td>Integridad (13.10)</td><td>Claves foráneas declaradas en la base</td><td>MongoDB; integridad por módulo dueño, fotos en lo emitido, <code>$jsonSchema</code>, control optimista (RN-PLA-044, RN-DAT-003, RN-DAT-007)</td><td>El medio no aplica al stack; el objetivo sí (ver aporte de verificador nocturno).</td></tr><tr><td>Fórmulas (5.6)</td><td>Reglas sin fórmulas libres</td><td>Reglas declarativas y, si no alcanzan, fórmulas en entorno aislado (RF-TAR-067, RF-TAR-068)</td><td>Sin fórmulas no se migran los cargos reales de ProCoop (tasas, subsidios, PIST/VAD en <code>CARGOS_ADICIONALES.FORMULA_*</code>).</td></tr><tr><td>Catálogo (5.2)</td><td>Un solo catálogo de ventas y compras con la cuenta en el concepto</td><td>Catálogos por dueño y cuentas asignadas por M15 (AGR-002)</td><td>El módulo de origen no elige cuentas.</td></tr><tr><td>Cabecera única (6.3)</td><td>Todos los comprobantes en una sola colección</td><td>Cabecera compartida como tipo, colecciones por módulo</td><td>Respeta la propiedad por módulo (RN-DAT-003).</td></tr><tr><td>Letra (6.1)</td><td>Letra derivada en un tipo genérico</td><td>Cada letra es un tipo con su código ARCA, elegido por matriz</td><td>ARCA codifica por tipo y letra.</td></tr><tr><td>Vencimientos (6.5)</td><td>Sin tope</td><td>De 1 a 4 (RF-FAC-086)</td><td>Coincide con ARCA y con la impresión.</td></tr><tr><td>Numeración (7.2)</td><td>Lo no autorizado vuelve a borrador</td><td>Número al emitir; si ARCA rechaza, se reenvía el mismo (DEC-035)</td><td>Volver a borrador deja huecos o fuerza a renumerar.</td></tr><tr><td>Imputación (9.3)</td><td>Impedir registrar un comprobante sin cuenta</td><td>Evento pendiente y bloqueo del cierre (PA-CON-02)</td><td>No frena la facturación masiva.</td></tr><tr><td>Compras (10.1)</td><td>Un documento que avanza por estados</td><td>Documentos separados vinculados ítem a ítem (M12)</td><td>Cada uno tiene dueño y efectos propios (stock, impuestos, asientos).</td></tr><tr><td>Identidad (12.1)</td><td>El usuario es una persona; migrar contraseñas con cambio obligatorio</td><td>Identidad global sin vínculo directo a la persona; no se migran contraseñas (PA-MIG-07, RN-MIG-013)</td><td>Privacidad entre cooperativas, y las contraseñas de ProCoop usan cifrado reversible.</td></tr><tr><td>Secretos (DD)</td><td>&quot;Fuera de la base&quot;</td><td>Cifrados en MongoDB con clave maestra en KMS (DEC-074)</td><td>Es una precisión: fuera de las colecciones de negocio.</td></tr><tr><td>Sesión (2.6)</td><td>Elegir la empresa al ingresar</td><td>La entidad se resuelve por documento (RF-CFG-137)</td><td>Un usuario opera varias entidades sin cambiar de sesión.</td></tr></tbody></table><h3 id="_4-2-errores-de-hecho-sobre-procoop-los-mas-relevantes" tabindex="-1">4.2 Errores de hecho sobre ProCoop (los más relevantes) <a class="header-anchor" href="#_4-2-errores-de-hecho-sobre-procoop-los-mas-relevantes" aria-label="Permalink to &quot;4.2 Errores de hecho sobre ProCoop (los más relevantes)&quot;">​</a></h3><ul><li><strong>Base imponible (8.3):</strong> <code>IMPUESTOS_X_CAT</code> no define la base; solo selecciona productos para un informe. La base sale de las fórmulas de cargos adicionales, y ProCoop sí calcula impuesto sobre impuesto.</li><li><strong>Simulación (5.7):</strong> dice que ProCoop no simula cuadros; tiene <code>SimularFacturasConCuadros</code> y la función <code>TotalSimulacionCuadro</code>.</li><li><strong>Cuadro aplicado (5.3):</strong> no se guarda en el renglón; <code>FACTURAS.COD_CUA</code> está en la cabecera y se completa recién al crear el cuadro siguiente.</li><li><strong>CESP (7.3, 7.6):</strong> dice que la liquidación de servicios públicos pide CAE o CAEA; en ProCoop se autoriza con CESP (<code>CESPAFIP</code>) y no pasa por WSFE.</li><li><strong>Ingresos Brutos (8.4):</strong> ProCoop no opera en una sola provincia; tiene importadores de Córdoba y ATER y exportadores ARBA, Santa Fe, La Pampa, Río Negro y SIRCAR.</li><li><strong>Liquidaciones propias (8.8):</strong> ProCoop sí genera Libro IVA, SICORE, SIRE y SIRCAR.</li><li><strong>Compras (10):</strong> <code>COMP_COM</code> es el remito, no la factura, y la orden de compra se maneja sobre <code>NPEDIDO</code>.</li><li><strong>Firmas de órdenes de pago (11.6):</strong> dice que está &quot;bien resuelto&quot;; la firma y entrega masiva no valida permisos ni registra el usuario, y los firmantes impresos salen de un parámetro de texto.</li><li><strong>Librador (11.5):</strong> <code>CTASUCE</code> sí guarda el CUIT del librador.</li><li><strong>Contraseñas (12.1):</strong> el riesgo es mayor que el que describe: cifrado reversible y contraseñas maestras en el código. De los &quot;siete lugares con credenciales&quot; se verifican cuatro.</li><li><strong>Transferencias (3.6):</strong> no es algo nuevo: existe <code>TRANSFER</code> con transferencia de cuenta, servicio y capital.</li><li><strong>Tablas mal interpretadas:</strong> <code>OCUPACIO</code> son ocupaciones de personas, no del inmueble; <code>POSTALES</code> son empresas de reparto, no zonas; <code>MEDSOC</code> es el medidor instalado, no el historial (<code>HIS_MEDSOC</code>); las áreas son tres tablas (<code>USERS_AREA</code>, <code>TUR_AREAS</code>, <code>ACT_AREAS</code>).</li><li><strong>Cifras:</strong> las tablas de extensión son unas 18 a 20, no 25; los &quot;módulos 19 a 26&quot; incluyen Informes y dejan fuera Comunicaciones.</li><li><strong>IVR (13.8):</strong> ProCoop no hace llamadas; exporta archivos para discadores externos.</li><li><strong>&quot;Sin claves foráneas&quot; (13.10):</strong> no está demostrado y hay indicios en contra.</li></ul><h3 id="_4-3-afirmaciones-normativas-sin-respaldo-a-verificar-con-el-contador-o-asesor-legal" tabindex="-1">4.3 Afirmaciones normativas sin respaldo (a verificar con el contador o asesor legal) <a class="header-anchor" href="#_4-3-afirmaciones-normativas-sin-respaldo-a-verificar-con-el-contador-o-asesor-legal" aria-label="Permalink to &quot;4.3 Afirmaciones normativas sin respaldo (a verificar con el contador o asesor legal)&quot;">​</a></h3><ul><li>IVA 21 % o 27 % según el uso del inmueble para el responsable inscripto.</li><li>Qué norma obliga a usar la liquidación de servicios públicos (el documento cita la RG 3571/2013, que nosotros tratamos como régimen de información), el alcance de la RG 5003 y el efecto de la RG 5866/2026.</li><li>Exención de Ingresos Brutos en Córdoba para cooperativas eléctricas.</li><li>Contribución Especial sobre el Capital Cooperativo.</li><li>Reforma de Ganancias de 2026 para cooperativas.</li><li>Si un recibo puede discriminar el IVA de los intereses (nosotros usamos nota de débito, PA-MOR-04) y si hay tope legal de pago en efectivo.</li></ul><h2 id="_5-elementos-nuevos-que-conviene-incorporar" tabindex="-1">5. Elementos nuevos que conviene incorporar <a class="header-anchor" href="#_5-elementos-nuevos-que-conviene-incorporar" aria-label="Permalink to &quot;5. Elementos nuevos que conviene incorporar&quot;">​</a></h2><h3 id="_5-1-prioridad-alta" tabindex="-1">5.1 Prioridad alta <a class="header-anchor" href="#_5-1-prioridad-alta" aria-label="Permalink to &quot;5.1 Prioridad alta&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Qué es</th><th>Dónde iría</th><th>Origen</th></tr></thead><tbody><tr><td>A1</td><td><strong>Compatibilidad en la factura agrupada:</strong> no mezclar servicios que exigen liquidación de servicios públicos con servicios de factura común (internet, telefonía, sepelio), salvo conceptos accesorios declarados por el contador. Hoy RN-FAC-040 puede meter internet dentro de una liquidación de servicios públicos.</td><td>M05 (RN-FAC-040, RF-FAC-067), M06, PA nueva</td><td>7.4</td></tr><tr><td>A2</td><td><strong>Validación normativa de la liquidación de servicios públicos:</strong> norma, vía de autorización (CESP, CAE o CAEA), RG 5003 y RG 5866/2026. Puede cambiar PA-FIS-02.</td><td>M06, PA nueva para el contador</td><td>7.3</td></tr><tr><td>A3</td><td><strong>Obligaciones y exenciones propias de la cooperativa:</strong> exenciones por actividad y jurisdicción con fundamento y vigencia; contribuciones propias (Capital Cooperativo); reforma de Ganancias.</td><td>M06 (y M17 para la base de capital), PA nueva</td><td>8.9</td></tr><tr><td>A4</td><td><strong>Completar DEC-064 (varias entidades jurídicas):</strong> <code>legalEntityId</code> en <code>associateMemberships</code> (para ser socio de la cooperativa y afiliado de la mutual a la vez), en <code>costCenters</code>, en el alcance de roles y en la auditoría, y ámbito &quot;entidad jurídica&quot; para parámetros.</td><td>M17, M15, T02, T04, T05</td><td>2.1, 2.5, 12.4</td></tr><tr><td>A5</td><td><strong>Persona única en todos los maestros:</strong> <code>personId</code> obligatorio en proveedores (M12), vendedores (M11), choferes y médicos (M18), con alta asistida. Hoy un socio contratista queda en dos fichas. Cambia RN-CMP-001.</td><td>M12, M11, M18, M01, PA nueva</td><td>3.1</td></tr><tr><td>A6</td><td><strong>Origen de las sucursales en la migración:</strong> RF-CFG-142 cita una columna que no existe; derivar <code>branches</code> de <code>PTOVENTA.SUC_COM</code> con revisión manual.</td><td>T04, T07</td><td>2.2</td></tr><tr><td>A7</td><td><strong>Personas sin ningún documento en la migración:</strong> regla explícita (hoy solo se tratan los documentos inválidos). Urgente para LAG.</td><td>T07, M01</td><td>15</td></tr><tr><td>A8</td><td><strong>Verificador nocturno de referencias entre colecciones</strong>, más una sección en T05 que explique cómo garantizamos integridad sin claves foráneas.</td><td>T05, T08</td><td>13.10</td></tr><tr><td>A9</td><td><strong>Fondos de cajas abiertas o sin rendir</strong> en la posición diaria de tesorería.</td><td>M14 (RF-TES-145, RF-TES-168)</td><td>11.1</td></tr><tr><td>A10</td><td><strong>Uso del suministro como condición opcional</strong> en la matriz de alícuotas de IVA, sujeta a confirmar la regla del 27 %.</td><td>M06 (<code>vatRateMatrix</code>)</td><td>4.4, 8.1</td></tr><tr><td>A11</td><td><strong>Ampliar la lista de secretos que la migración suprime</strong> (RN-MIG-013): sumar la clave web de <code>SOCIOS</code>, la clave del proveedor de IA guardada en <code>VARIABLE</code> y las credenciales de proveedores, profesionales y empleados si aparecen en la base real; verificar que <code>CUPONTAR</code> no traiga números de tarjeta (DEC-091).</td><td>T07, T08</td><td>12.1, 11.7</td></tr></tbody></table><h3 id="_5-2-prioridad-media" tabindex="-1">5.2 Prioridad media <a class="header-anchor" href="#_5-2-prioridad-media" aria-label="Permalink to &quot;5.2 Prioridad media&quot;">​</a></h3><ul><li><strong>Zonificación por tipo con vigencia</strong> (tributaria, tarifaria, de facturación, postal, técnica) y asignación por inmueble, cuenta o tramo de calle (T04 <code>zones</code>, consumida por M01, M03, M04 y M10).</li><li><strong>Frentes con vigencia</strong> y zona tributaria por frente, para tasas municipales por metro de frente (M01, M04; relevar con la piloto).</li><li><strong>Efectos explícitos por tipo de comprobante:</strong> deuda o crédito, libro IVA, stock, fondos, contabilización (M05 <code>voucherTypes</code>).</li><li><strong>Preferencia declarativa en tarifas:</strong> justificar cada fórmula y reportar la proporción de reglas con fórmula (M04).</li><li><strong>Significado de los coeficientes</strong> del cuadro (M04 <code>categoryCoefficients</code>).</li><li><strong>Clase fiscal fotografiada en el renglón</strong> de la factura (M05).</li><li><strong>Régimen en las percepciones sufridas</strong> de compras (M12).</li><li><strong>Porcentaje de crédito fiscal computable calculado</strong> por sección (M06 → M15).</li><li><strong>Sucursal y obra como dimensiones explícitas</strong> del asiento (M15).</li><li><strong>Catálogo transversal de motivos</strong> por tipo de operación (T04, T11, T02).</li><li><strong>Códigos externos de organismos con vigencia</strong> (T04).</li><li><strong>Prioridad por defecto por campo al fusionar personas</strong> (T07, M01).</li><li><strong>Catálogo de asistentes de alta</strong> (socio, cliente ocasional, proveedor, adherente, empleado) (M01, T03).</li></ul><h3 id="_5-3-prioridad-baja" tabindex="-1">5.3 Prioridad baja <a class="header-anchor" href="#_5-3-prioridad-baja" aria-label="Permalink to &quot;5.3 Prioridad baja&quot;">​</a></h3><p>Tramos de calle con zona y código postal por defecto; detección de edificios en la migración; servicios disponibles del inmueble (agua, cloaca, pavimento); aviso por incoherencia entre uso del inmueble y categoría; costos del cuadro como lista extensible; vista de la cadena documental; vista previa del asiento al registrar la factura de proveedor; base imponible declarativa por lista de conceptos; percepción de IVA en regla propia; límites por medio de pago; jerarquía de áreas de atención.</p><h2 id="_6-inconsistencias-internas-de-nuestra-especificacion-detectadas" tabindex="-1">6. Inconsistencias internas de nuestra especificación detectadas <a class="header-anchor" href="#_6-inconsistencias-internas-de-nuestra-especificacion-detectadas" aria-label="Permalink to &quot;6. Inconsistencias internas de nuestra especificación detectadas&quot;">​</a></h2><p>Son correcciones nuestras, independientes del documento externo:</p><ol><li>T07 mapea <code>USERS_AREA</code> a <code>orgUnits</code>, colección que no existe.</li><li><code>RESPONSA</code> tiene dos destinos: M01 la trata como garantes y T07 como técnicos de campo; el catálogo respalda a T07.</li><li>RF-CFG-142 cita sucursales en <code>EMPRESAS</code> y <code>CAJASJP</code>, que no tienen esa columna.</li><li>DEC-064 no llegó a <code>associateMemberships</code>, <code>costCenters</code> ni al alcance de roles.</li><li>T07 da 89 columnas para <code>PROD_SER</code> y 56 para <code>TIPO_FAC</code>; el catálogo dice 90 y 57.</li><li>El enumerado <code>tariffServiceSettings.proration.method</code> de M04 no coincide con los métodos de RN-TAR-049.</li><li><code>numberSequences.authorizationType</code> de M05 no admite <code>CESP</code>, aunque M06 lo usa.</li><li><code>numberSequences.billingGroupId</code> figura como obligatorio en la tabla y como opcional en la descripción.</li><li>T07 apunta a una colección <code>recordLinks</code> no definida.</li><li>El IVR se trata distinto en tres anexos: T09 solo exporta contactos a un discador, T06 lo trata como integración opcional en O10 (FI-INT-66 dice además &quot;Soportado por ProCoop&quot; para un IVR que ProCoop no tiene) y T07 lo &quot;reemplaza por canal de voz&quot;, que T09 no define. Hay que alinear T09, T06, T07 y M08.</li><li>El encabezado de M07 dice 14 tablas del §7 del catálogo; son 13.</li></ol><h2 id="_7-recomendacion" tabindex="-1">7. Recomendación <a class="header-anchor" href="#_7-recomendacion" aria-label="Permalink to &quot;7. Recomendación&quot;">​</a></h2><ol><li><strong>No adoptar el documento como fuente.</strong> Sus principios útiles ya están en nuestra especificación y su arquitectura contradice DEC-001 y DEC-002.</li><li><strong>Corregir las inconsistencias internas de la sección 6</strong>, que no requieren decisión.</li><li><strong>Registrar como DEC o PA las incorporaciones de prioridad alta</strong> (sección 5.1). A1, A2, A3 y A10 necesitan al contador; A4 a A9 y A11 son decisiones de diseño.</li><li><strong>Llevar al contador la lista de la sección 4.3.</strong></li><li><strong>Devolver al autor</strong> la lista de errores de la sección 4.2 y los 49 pendientes que ya están respondidos (detalle en <code>_trabajo/contraste-14-16.md</code>, sección 16), para que actualice su documento si lo sigue usando.</li></ol><p>Los enlaces de la sección 17 del documento apuntan a artefactos externos de claude.ai que no están en el repositorio; no se verificaron.</p>',33)])])}const g=o(i,[["render",n]]);export{m as __pageData,g as default};
